template.css:
.dicom-viewport {
  display: flex;
  flex-direction: column;
  background: #000;
  border: 2px solid #00ff88;
  border-radius: 8px;
  overflow: hidden;
  height: 100%;
}
.viewport-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 15px;
  background: #1a1a2e;
  border-bottom: 1px solid #00ff88;
}
.viewport-title {
  color: #00ff88;
  font-weight: bold;
  font-size: 1.1em;
}
.viewport-canvas-container {
  position: relative;
  flex: 1;
  background: #000;
  overflow: hidden;
}
.viewport-canvas {
  width: 100%;
  height: 100%;
  cursor: crosshair;
}
.viewport-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  color: #00ff88;
  font-size: 0.85em;
  font-family: 'Courier New', monospace;
}
.overlay-top-left {
  position: absolute;
  top: 10px;
  left: 10px;
}
.overlay-top-right {
  position: absolute;
  top: 10px;
  right: 10px;
  text-align: right;
}
.overlay-bottom-left {
  position: absolute;
  bottom: 10px;
  left: 10px;
}
.overlay-bottom-right {
  position: absolute;
  bottom: 10px;
  right: 10px;
  text-align: right;
}
.overlay-item {
  margin: 3px 0;
  text-shadow: 1px 1px 2px #000;
}
.viewport-controls {
  display: flex;
  gap: 8px;
  padding: 10px;
  background: #1a1a2e;
  border-top: 1px solid #00ff88;
}
.tool-btn {
  padding: 8px 12px;
  background: #0a0a0a;
  border: 1px solid #333;
  border-radius: 4px;
  color: #00ff88;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 1.2em;
}
.tool-btn:hover {
  border-color: #00ff88;
  background: rgba(0, 255, 136, 0.1);
}
.tool-btn.active {
  border-color: #00ccff;
  background: rgba(0, 204, 255, 0.2);
  box-shadow: 0 0 10px rgba(0, 204, 255, 0.3);
}

