function initDicomViewport(element, config) {
  const canvas = element.querySelector('.viewport-canvas');
  const ctx = canvas.getContext('2d');
  let currentImage = null;
  let viewport = {
    zoom: 1.0,
    pan: { x: 0, y: 0 },
    windowLevel: config.defaultWindowLevel || 40,
    windowWidth: config.defaultWindowWidth || 400
  };

  function loadImage(imageData) {
    currentImage = imageData;
    renderImage();
  }

  function renderImage() {
    if (!currentImage) return;

    // Apply window/level and render
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Actual DICOM rendering would go here
    // This is a placeholder for the rendering logic

    updateOverlay();
  }

  function updateOverlay() {
    const overlay = element.querySelector('.viewport-overlay');
    overlay.querySelector('.overlay-bottom-right .overlay-item:nth-child(1)').textContent = 
      `W: ${viewport.windowWidth} L: ${viewport.windowLevel}`;
    overlay.querySelector('.overlay-bottom-right .overlay-item:nth-child(2)').textContent = 
      `Zoom: ${(viewport.zoom * 100).toFixed(0)}%`;
  }

  // Tool button handlers
  element.querySelectorAll('.tool-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const tool = this.dataset.tool;
      handleTool(tool);
    });
  });

  function handleTool(tool) {
    console.log('Tool activated:', tool);
    // Implement tool logic
  }

  return { loadImage, renderImage, viewport };
}
